		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");

			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.pxc.byq!=undefined){
			
			if(gameController.ehm!=parseInt(tmpMess[1])){
				
			gameController.ehm=parseInt(tmpMess[1]);	
			gameController.ikk=parseInt(tmpMess[1]);	
			gameController.pxc.byq.ynt("creditd", "#qha", [gameController.ped(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
